func resolveAgentInstallNamespace(userNamespace string) (string, string) {
	sysNs := strings.TrimSpace(os.Getenv("AGENT_INSTALL_NAMESPACE"))
	if sysNs == "" {
		return userNamespace, ""
	}
	return sysNs, userNamespace
}
